import 'package:flutter/material.dart'; import 'package:provider/provider.dart'; import '../services/recipe_store.dart';
class RecipeDetailScreen extends StatelessWidget { const RecipeDetailScreen({super.key, required this.recipeId}); final String recipeId;
 @override Widget build(BuildContext context){ final store=context.watch<RecipeStore>(); final r=store.findById(recipeId); if(r==null) return Scaffold(appBar:AppBar(), body:const Center(child:Text('Recipe unavailable'))); final colors=Theme.of(context).colorScheme; return Scaffold(body:CustomScrollView(slivers:[SliverAppBar(pinned:true, expandedHeight:270, actions:[IconButton(onPressed:()=>store.toggleFavorite(r.id), icon:Icon(store.isFavorite(r.id)?Icons.favorite:Icons.favorite_border))], flexibleSpace:FlexibleSpaceBar(background:r.imagePath==null?ColoredBox(color:colors.primaryContainer,child:Icon(Icons.rice_bowl,size:90,color:colors.onPrimaryContainer)):Image.asset(r.imagePath!,fit:BoxFit.cover,errorBuilder:(_,__,___)=>ColoredBox(color:colors.primaryContainer,child:Icon(Icons.rice_bowl,size:90,color:colors.onPrimaryContainer))))), SliverPadding(padding:const EdgeInsets.all(20), sliver:SliverList(delegate:SliverChildListDelegate([Text(r.name,style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)), const SizedBox(height:8), Text('${r.region} · ${r.category} · ${r.diet}',style:TextStyle(color:colors.onSurfaceVariant)), const SizedBox(height:16), Wrap(spacing:8,children:[_tag(context,'${r.totalMinutes} min'),_tag(context,r.difficulty),if(r.calories!=null)_tag(context,'${r.calories} kcal')]), const SizedBox(height:24), Text('Ingredients',style:Theme.of(context).textTheme.titleLarge), const SizedBox(height:8), ...r.ingredients.map((x)=>ListTile(leading:Icon(Icons.circle,size:9,color:colors.primary), title:Text(x), dense:true, contentPadding:EdgeInsets.zero)), const SizedBox(height:18), Text('Method',style:Theme.of(context).textTheme.titleLarge), const SizedBox(height:8), if(r.steps.isNotEmpty)...r.steps.asMap().entries.map((e)=>ListTile(leading:CircleAvatar(child:Text('${e.key+1}')), title:Text(e.value), contentPadding:EdgeInsets.zero)) else Text(r.method), if(r.photoCredit!=null) Padding(padding:const EdgeInsets.only(top:18),child:Text(